```python
def solve_sudoku(board):
    # Find an empty cell
    empty_cell = next((i, j) for i, row in enumerate(board) for j, num in enumerate(row) if num == 0)
    i, j = empty_cell

    # Try each digit 1-9
    for digit in range(1, 10):
        # Check if the digit can be placed in the current cell
        if can_place(board, i, j, str(digit)):
            # Place the digit in the current cell
            board[i][j] = str(digit)

            # If the board is solved, return it
            if is_solved(board):
                return board

            # Backtrack and try the next digit
            solve_sudoku(board)

            # If no solution is found with the current digit, remove it and try the next one
            board[i][j] = '0'

    # If no solution is found, return None
    return None

def can_place(board, i, j, digit):
    # Check row
    for row_i in range(len(board)):
        if board[row_i][j] == digit:
            return False

    # Check column
    for col_j in range(len(board[0])):
        if board[i][col_j] == digit:
            return False

    # Check 3x3 grid
    grid_i = i // 3 * 3
    grid_j = j // 3 * 3

    for row_i in range(grid_i, grid_i + 3):
        for col_j in range(grid_j, grid_j + 3):
            if board[row_i][col_j] == digit:
                return False

    return True

def is_solved(board):
    for row in board:
        if 0 in row:
            return False
    return True

# Example usage
board = [
    [5, 3, 0, 0, 7, 0, 0, 0, 0],
    [6, 0, 0, 1, 9, 5, 0, 0, 0],
    [0, 9, 8, 0, 0, 0, 0, 6, 0]
]

solved_board = solve_sudoku(board)
print(solved_board)
```

This program defines three helper functions: `can_place`, which checks if a digit can be placed in a cell, `is_solved`, which checks if the board is solved, and `solve_sudoku`, which recursively tries to solve the Sudoku puzzle. The example usage at the end of the program demonstrates how to use this function to solve a sample Sudoku puzzle.
